(function(root){
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0];const delim=(first.match(/;/g)||[]).length>(first.match(/,/g)||[]).length?';':',';let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(quoted)quoted=false;else if(cell==='')quoted=true;else throw Error('Guillemet inattendu dans le CSV.');}else if(c===delim&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Guillemet non fermé dans le CSV.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(rows.length<2)throw Error('Le fichier doit contenir un en-tête et au moins une intervention.');if(rows.length>2001)throw Error('Maximum 2 000 interventions par fichier.');const headers=rows.shift().map(x=>x.trim().toLowerCase());const required=['date','client','intervention','duree_minutes','statut'];for(const h of required)if(headers.filter(x=>x===h).length!==1)throw Error('Colonne absente ou répétée : '+h);return rows.map((r,i)=>{if(r.length!==headers.length)throw Error('Ligne '+(i+2)+' : nombre de colonnes incorrect.');const o={};required.forEach(h=>o[h]=r[headers.indexOf(h)].trim());let d=o.date.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);if(d)o.date=d[3]+'-'+d[2]+'-'+d[1];if(!/^\d{4}-\d{2}-\d{2}$/.test(o.date)||!Number.isFinite(Date.parse(o.date))||new Date(o.date).toISOString().slice(0,10)!==o.date)throw Error('Ligne '+(i+2)+' : date invalide.');if(!o.client||!o.intervention)throw Error('Ligne '+(i+2)+' : client et intervention obligatoires.');if(!/^\d+(?:[.,]\d+)?$/.test(o.duree_minutes))throw Error('Ligne '+(i+2)+' : durée positive en minutes attendue.');o.minutes=Number(o.duree_minutes.replace(',','.'));if(o.minutes>100000)throw Error('Ligne '+(i+2)+' : durée trop élevée.');const status=o.statut.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();o.statut=({'resolu':'Résolu','en cours':'En cours','a planifier':'À planifier'})[status];if(!o.statut)throw Error('Ligne '+(i+2)+' : statut attendu Résolu, En cours ou À planifier.');return o;});}
function summarize(rows){return{count:rows.length,minutes:rows.reduce((n,r)=>n+r.minutes,0),resolved:rows.filter(r=>r.statut==='Résolu').length};}root.RapportCore={parseCSV,summarize};if(typeof module!=='undefined')module.exports=root.RapportCore;
})(globalThis);
